    [1119,60172,"Yuan","Jaxin","Xin should be very satisfied with this final report. He has demonstrated consistent effort in his subjects, particularly Chinese and Literature and English ESL, where he has achieved some excellent results. Xin is to be congratulated for the mature and organised approach he has taken in order to achieve his goals. Xin has demonstrated an enduring commitment to his personal presentation, Community Service and House activities, and in doing so, has acted as a wonderful ambassador for the School. He has supported the School’s Christian ethos and displayed concern, compassion, and care for others. I would like to wish Xin God’s richest blessings and encourage him to approach the future with continued determination and energy."],
];

switch ($yearLevel) {
    case 7:
    case 8:
    case 9:
    case 10:
        $monthAndDay = $semester === 1 ? '06-12' : '12-12';  // Jun 12th : Dec 12th
        break;
    case 11:
        $monthAndDay = $semester === 1 ? '06-12' : '09-12';  // Jun 12th : Sep 12th
        break;
    case 12:
        $monthAndDay = $semester === 1 ? '03-25' : '09-12';  // Mar 25th : Sep 12th
        break;
    default:
        $logger->error("Unknown year level: $yearLevel");
        exit(1);
}
$logger->info("Month and Day: $monthAndDay");

$date = new Alaress_Date_Format("$year-$monthAndDay", Alaress_Date_Format::DATABASE_DATE_FORMAT);


$insertStatement = $db->prepareQuery("
    INSERT INTO pastoral (
        owner_id, 
        student_id, 
        type_id, 
        heading, 
        body_public, 
        modified_by_user_id, 
        created_at, 
        updated_at
    ) VALUES (
        :owner_id,
        :student_id,
        (SELECT value FROM config WHERE name = 'tigs_crp_pastoral_type'),
        :heading,
        :body_public,
        :modified_by_user_id,
        :created_at,
        :updated_at
    )
");

foreach ($data as $rowId => $row) {
    if (0 === $rowId) {
        // Ignore headers
        continue;
    }
    [$deanId, $studentId, $surname, $preferred, $comment] = $row;
    $dean    = $userMapper->findByExternalId($deanId);
    $student = $userMapper->findByExternalId($studentId);

    // Sanity check
    if ($student->getLastname() !== $surname) {
        $logger->warning("Lastname: {$student->getLastname()} !== Surname: {$surname}");
    } else {
        $logger->debug("Lastname: {$student->getLastname()} === Surname: {$surname}");
    }
    if ($student->getFirstname() !== $preferred) {
        echo "Lastname: {$student->getFirstname()} !== Surname: {$preferred}<br>\n";
    } else {
        $logger->debug("Lastname: {$student->getFirstname()} === Surname: {$preferred}");
    }

    $heading = "Year $yearLevel $year Semester $semester Dean's Comment";
    $logger->info("Inserting comment for student {$student->getId()} '$heading'");
    if($perform){
        $insertStatement->execute([
            'owner_id'            => $dean->getId(),
            'student_id'          => $student->getId(),
            'heading'             => $heading,
            'body_public'         => "<p>$comment</p>",
            'modified_by_user_id' => $dean->getId(),
            'created_at'          => $date->getDatabase(),
            'updated_at'          => $date->getDatabase(),
        ]);
    }
}

die('done');
